python3 - <<'PY'
import json, re, unicodedata, os, shutil

base = os.getcwd()
env = os.path.join(base, 'environment')

with open(os.path.join(env, 'jielong.txt'), encoding='utf-8') as f:
    lines = f.read().splitlines()
with open(os.path.join(env, 'peers.json'), encoding='utf-8') as f:
    peers_doc = json.load(f)
with open(os.path.join(env, 'orders.json'), encoding='utf-8') as f:
    orders_doc = json.load(f)

self_id = peers_doc['self_id']
peers = peers_doc['peers']

def strip_emoji(s):
    # Remove leading/trailing emoji / pictographs / variation selectors / ZWJ.
    pat = re.compile(
        r'^(?:[\U0001F000-\U0001FAFF\u2600-\u27BF\u2B00-\u2BFF\uFE0F\u200D\U0001F1E6-\U0001F1FF]+)|'
        r'(?:[\U0001F000-\U0001FAFF\u2600-\u27BF\u2B00-\u2BFF\uFE0F\u200D\U0001F1E6-\U0001F1FF]+)$'
    )
    prev = None
    while prev != s:
        prev = s
        s = pat.sub('', s)
    return s

def to_halfwidth(s):
    out = []
    for ch in s:
        code = ord(ch)
        if code == 0x3000:
            out.append(' ')
        elif 0xFF01 <= code <= 0xFF5E:
            out.append(chr(code - 0xFEE0))
        else:
            out.append(ch)
    return ''.join(out)

def norm_nick(s):
    return to_halfwidth(strip_emoji(s.strip())).strip()

line_re = re.compile(r'^(\d+)\s*[.、)）]\s*(.*)$')
date_re = re.compile(r'^\d{1,2}\.\d{1,2}')

resolution = []
for line in lines:
    if not line.strip():
        continue
    if line.startswith('#接龙') or line.startswith('——') or line.strip() == '参与接龙':
        continue
    if date_re.match(line):
        continue
    m = line_re.match(line)
    if not m:
        continue
    seq = int(m.group(1))
    raw = m.group(2).strip()
    work = raw

    # Arrival time at end, e.g. 9:00.
    arrival = None
    tm = re.search(r'(?:^|\s)(\d{1,2}):(\d{2})\s*$', work)
    if tm:
        h, mi = int(tm.group(1)), int(tm.group(2))
        if h < 12:
            h += 12
        arrival = (h, mi)
        arrival_text = f'{h}:{mi:02d}'
        work = work[:tm.start()].strip()

    # Slot qualifier at end: only/只 optional + 第N场 (Arabic, fullwidth, Chinese).
    slots = ['19:00', '20:20']
    qm = re.search(r'(?:\s*(?:only|只)\s*)?第\s*([1-2１２一二])\s*场\s*$', work, re.I)
    if qm:
        q = qm.group(1)
        if q in ('1', '１', '一'):
            slots = ['19:00']
        else:
            slots = ['20:20']
        work = work[:qm.start()].strip()

    nickname = work.strip()

    if arrival is not None:
        minutes = arrival[0] * 60 + arrival[1]
        if 19 * 60 <= minutes <= 20 * 60 + 10:
            slots = ['19:00']
        elif 20 * 60 + 20 <= minutes <= 21 * 60 + 30:
            slots = ['20:20']

    # Generic "friend" entries never get an ID.
    is_generic = '朋友' in nickname

    matches = []
    if not is_generic:
        n_norm = norm_nick(nickname)
        for p in peers:
            candidates = [p['name']] + list(p.get('aliases', []))
            hit = False
            for c in candidates:
                if nickname == c:
                    hit = True
                    break
                if n_norm and n_norm == norm_nick(c):
                    hit = True
                    break
            if hit:
                matches.append(p['id'])
    matches = list(dict.fromkeys(matches))

    if is_generic:
        status, sid = 'unmatched', None
    elif len(matches) == 1:
        status, sid = 'matched', matches[0]
    elif len(matches) > 1:
        status, sid = 'conflict', None
    else:
        status, sid = 'unmatched', None

    note = ''
    if sid == self_id:
        slots = []
        note = '发起人本人，跳过，不进入任何分单名单'
    elif status == 'unmatched':
        if is_generic:
            note = '泛称（含「朋友」），代他人报名，无法对应具体学号'
        else:
            note = '别名表无匹配记录，待人工确认'
    elif status == 'conflict':
        note = '命中多个候选学号：' + '、'.join(matches) + '，待人工确认'
    elif arrival is not None:
        note = f'到达时刻 {arrival_text}，落入 {slots[0]} 场次' if slots else f'到达时刻 {arrival_text}'

    resolution.append({
        'seq': seq,
        'raw': raw,
        'sid': sid,
        'status': status,
        'slots': slots,
        'note': note,
    })

resolution.sort(key=lambda x: x['seq'])

# ---------------- plan ----------------
orders = orders_doc['orders']
capacity = orders_doc['capacity_per_order']

plan = []
for o in orders:
    plan.append({
        'orderNo': o['orderNo'],
        'add': [],
        'skip': [],
        'reject': [],
        'reason': '',
    })

by_order_no = {p['orderNo']: p for p in plan}

# Group order indices by slot, preserving appearance order.
slot_indices = {}
for i, o in enumerate(orders):
    slot_indices.setdefault(o['startTime'], []).append(i)

for slot, idxs in slot_indices.items():
    participants = []
    seen = set()
    for r in resolution:
        if r['status'] != 'matched' or r['sid'] is None or r['sid'] == self_id:
            continue
        if slot not in r['slots']:
            continue
        if r['sid'] in seen:
            continue
        seen.add(r['sid'])
        participants.append(r['sid'])

    # Anyone already present in a same-slot order is idempotently skipped there.
    handled = set()
    for i in idxs:
        existing = set(orders[i]['peers'])
        for sid in participants:
            if sid in existing:
                by_order_no[orders[i]['orderNo']]['skip'].append(sid)
                handled.add(sid)

    remaining = [sid for sid in participants if sid not in handled]

    for sid in remaining:
        placed = False
        saw_non_block = False
        for i in idxs:
            o = orders[i]
            if o['blockType'] != 2:
                saw_non_block = True
                continue
            current = len(o['peers']) + len(by_order_no[o['orderNo']]['add'])
            if current < capacity:
                by_order_no[o['orderNo']]['add'].append(sid)
                placed = True
                break
        if placed:
            continue
        # Overflow: reject at the non-block order if one exists in this slot,
        # otherwise at the slot's last order.
        non_block = [i for i in idxs if orders[i]['blockType'] != 2]
        target = non_block[0] if non_block else idxs[-1]
        by_order_no[orders[target]['orderNo']]['reject'].append(sid)

# Reasons.
for i, o in enumerate(orders):
    p = by_order_no[o['orderNo']]
    is_block = o['blockType'] == 2
    existing_n = len(o['peers'])
    if is_block:
        after = existing_n + len(p['add'])
        txt = f"{o['startTime']} 场次包场单：现有同伴{existing_n}人，容量{capacity}，新增{len(p['add'])}人，新增后{after}人"
        if after >= capacity:
            txt += '（满员）'
        txt += '。'
    else:
        txt = f"{o['startTime']} 场次散场单（blockType={o['blockType']}，不可新增同伴）："
        if p['reject']:
            txt += f"包场单已满员，{len(p['reject'])}名溢出人员记入 reject。"
        else:
            txt += '本单不接收新增同伴。'
    if p['skip']:
        txt += '已在现有同伴中的学号 ' + '、'.join(p['skip']) + ' 记入 skip，本场次不重复加入。'
    p['reason'] = txt

# Write outputs.
def dump(path, data):
    with open(path, 'w', encoding='utf-8', newline='\n') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write('\n')

dump(os.path.join(base, 'resolution.json'), resolution)
dump(os.path.join(base, 'plan.json'), plan)

# Suggested supporting copies under output/.
outdir = os.path.join(base, 'output')
inpdir = os.path.join(outdir, 'inputs')
os.makedirs(inpdir, exist_ok=True)
for name in ('jielong.txt', 'peers.json', 'orders.json'):
    shutil.copyfile(os.path.join(env, name), os.path.join(inpdir, name))
dump(os.path.join(outdir, 'resolution.json'), resolution)
dump(os.path.join(outdir, 'plan.json'), plan)
dump(os.path.join(outdir, 'meta.json'), {
    'product': 'jielong-fullchain',
    'version': '1.0.0',
    'operator': 'dsh / deeps
